@Test
    void testFromPoints() {
        // act/assert
        checkGreatCircle(GreatCircles.fromPoints(
                    Point2S.of(0, Angle.PI_OVER_TWO),
                    Point2S.of(Angle.PI_OVER_TWO, Angle.PI_OVER_TWO),
                    TEST_PRECISION),
                Z, X);

        checkGreatCircle(GreatCircles.fromPoints(
                Point2S.of(0, Angle.PI_OVER_TWO),
