@Override
        public RegionLocation classify(final TestPoint1D pt) {
            if (!empty) {
                final double sign = PartitionTestUtils.PRECISION.signum(pt.getX());

                if (sign < 0) {
                    return RegionLocation.INSIDE;
                } else if (sign == 0) {
                    return RegionLocation.BOUNDARY;
                }
            }
            return RegionLocation.OUTSIDE;
        }

