@Test
    void testGetBounds_mixedFiniteAndInfiniteBoundaries() {
        // arrange
        final PlaneConvexSubset inf = Planes.fromPointAndNormal(Vector3D.ZERO, Vector3D.Unit.PLUS_Z, TEST_PRECISION)
                .span()
