        final QuaternionRotation rotation = QuaternionRotation.fromAxisAngle(Vector3D.Unit.PLUS_Z, Angle.PI_OVER_TWO);

        final AffineTransformMatrix3D transform = AffineTransformMatrix3D.createRotation(center, rotation);

